import * as THREE from 'three/webgpu';
import {
  tslFn,
  uv,
  length,
  sub,
  mul,
  vec2,
  float,
  mix,
  smoothstep,
  color,
} from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {Object} assets
 * @property {string} assets.meshUrl
 * @property {Array} cinematicPrimitives
 * @property {Object} position
 * @property {Object} rotation
 * @property {Object} scale
 * @property {Object} textContent
 * @property {Object} textContent.headline
 * @property {string} textContent.headline.text
 * @property {Object} textContent.caption
 * @property {string} textContent.caption.text
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader
 * @property {Object.<string,Function>} primitives
 * @property {Object} fontAtlas
 * @property {Function} fontAtlas.createText
 */

/**
 * Creates the Orrery mechanism node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new THREE.Group();

  // Apply placement transforms
  if (config.position) root.position.set(config.position[0], config.position[1], config.position[2]);
  if (config.rotation) root.rotation.set(config.rotation[0], config.rotation[1], config.rotation[2]);
  if (config.scale) root.scale.set(config.scale[0], config.scale[1], config.scale[2]);

  // ------------------------------------------------------------------------
  // Load primary gear from GLB
  // ------------------------------------------------------------------------
  const glb = ctx.glbLoader(config.assets?.meshUrl);
  const primaryGear = glb.scene.clone();

  // Normalise primary gear diameter to 1.6 units
  const bbox = new THREE.Box3().setFromObject(primaryGear);
  const size = new THREE.Vector3();
  bbox.getSize(size);
  const maxDim = Math.max(size.x, size.y, size.z);
  const primaryScaleFactor = 1.6 / maxDim;
  primaryGear.scale.setScalar(primaryScaleFactor);
  primaryGear.position.set(0, 0, 0);

  // Apply machined‑steel PBR overrides
  primaryGear.traverse((obj) => {
    if (obj.isMesh && obj.material && obj.material.isMeshPhysicalMaterial) {
      const m = obj.material;
      m.roughness = 0.5;
      m.metalness = 0.55;
      m.clearcoat = 0.2;
      m.clearcoatRoughness = 0.3;
      m.anisotropy = 0.7;
      m.needsUpdate = true;
    }
  });

  // ------------------------------------------------------------------------
  // Secondary gear (scaled, positioned and opposite rotation)
  // ------------------------------------------------------------------------
  const secondaryGear = primaryGear.clone();
  const secondaryDesiredDiameter = 0.9;
  const secondaryScaleFactor = secondaryDesiredDiameter / maxDim;
  secondaryGear.scale.setScalar(secondaryScaleFactor);
  secondaryGear.position.set(1.15, 0.35, -0.1);

  // ------------------------------------------------------------------------
  // Jewel pivot (transparent red sphere)
  // ------------------------------------------------------------------------
  const jewelGeom = new THREE.SphereGeometry(0.12, 32, 32);
  const jewelMat = new THREE.MeshPhysicalMaterial({
    color: new THREE.Color('#ff2a38'),
    transmission: 0.6,
    ior: 1.76,
    emissive: new THREE.Color('#ff2a38'),
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 0,
    clearcoat: 0,
    clearcoatRoughness: 0,
  });
  const jewel = new THREE.Mesh(jewelGeom, jewelMat);
  jewel.position.set(0, 0, 0);

  // ------------------------------------------------------------------------
  // Arbor shafts (ink cylinders)
  // ------------------------------------------------------------------------
  const shaftGeom = new THREE.CylinderGeometry(0.05, 0.05, 0.8, 16);
  const shaftMat = new THREE.MeshPhysicalMaterial({ color: new THREE.Color('#16161d') });
  const shaftPrimary = new THREE.Mesh(shaftGeom, shaftMat);
  shaftPrimary.rotation.x = Math.PI / 2;
  shaftPrimary.position.set(0, 0, 0);
  const shaftSecondary = shaftPrimary.clone();
  shaftSecondary.position.copy(secondaryGear.position);

  // ------------------------------------------------------------------------
  // Contact shadow ellipse (simple plane with opacity)
  // ------------------------------------------------------------------------
  const shadowGeom = new THREE.PlaneGeometry(2.6, 1.2);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x000000,
    opacity: 0.5,
    transparent: true,
    depthWrite: false,
  });
  const shadow = new THREE.Mesh(shadowGeom, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.2, 0);

  // ------------------------------------------------------------------------
  // Backdrop plane with radial gradient (TSL node material)
  // ------------------------------------------------------------------------
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new THREE.NodeMaterial();
  const gradientNode = tslFn(() => {
    const uvCoord = uv(); // [0,1] range
    const dist = length(sub(uvCoord, vec2(0.5, 0.5)));
    const c0 = color('#0b0b10');
    const c1 = color('#101017');
    const c2 = color('#16161d');
    const stop0 = float(0.0);
    const stop1 = float(0.65);
    const stop2 = float(1.0);
    const mix01 = mix(c0, c1, smoothstep(stop0, stop1, dist));
    return mix(mix01, c2, smoothstep(stop1, stop2, dist));
  })();
  backdropMat.colorNode = gradientNode;
  backdropMat.side = THREE.DoubleSide;
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -3);

  // ------------------------------------------------------------------------
  // Assemble hierarchy
  // ------------------------------------------------------------------------
  root.add(primaryGear, secondaryGear, jewel, shaftPrimary, shaftSecondary, shadow, backdrop);

  // ------------------------------------------------------------------------
  // Text nodes (headline & caption) via fontAtlas helper
  // ------------------------------------------------------------------------
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
    const headlineConfig = config.textContent?.headline || { text: 'The going train' };
    const headline = ctx.fontAtlas.createText(headlineConfig.text, {
      family: 'Lora',
      size: 68,
      weight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.1,
      color: '#e8ecf2',
    });
    headline.position.set(0, -1.7, 0.01);
    root.add(headline);

    const captionConfig = config.textContent?.caption || { text: '34 COMPONENTS / HAND-FINISHED' };
    const caption = ctx.fontAtlas.createText(captionConfig.text, {
      family: 'JetBrains Mono',
      size: 18,
      weight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: '#e8ecf2',
    });
    caption.position.set(0, -2.1, 0.01);
    root.add(caption);
  }

  // ------------------------------------------------------------------------
  // Gear rotation animation (continuous)
  // ------------------------------------------------------------------------
  const rotationTimeline = gsap.timeline({ repeat: -1, paused: false });
  const primaryPeriod = (2 * Math.PI) / 0.08; // seconds for one full turn
  const secondaryPeriod = (2 * Math.PI) / 0.142; // seconds for one full turn (opposite)
  rotationTimeline
    .to(
      primaryGear.rotation,
      { y: `+=${Math.PI * 2}`, duration: primaryPeriod, ease: 'none' },
      0,
    )
    .to(
      secondaryGear.rotation,
      { y: `-=${Math.PI * 2}`, duration: secondaryPeriod, ease: 'none' },
      0,
    );

  // ------------------------------------------------------------------------
  // Apply cinematic primitives defined in the config
  // ------------------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // ------------------------------------------------------------------------
  // Cleanup routine
  // ------------------------------------------------------------------------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    rotationTimeline.kill();

    const disposeTraverser = (obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose();
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose && m.dispose());
        } else {
          obj.material?.dispose && obj.material.dispose();
        }
      }
    };
    primaryGear.traverse(disposeTraverser);
    secondaryGear.traverse(disposeTraverser);
    jewelGeom.dispose();
    jewelMat.dispose();
    shaftGeom.dispose();
    shaftMat.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
    backdropGeom.dispose();
    backdropMat.dispose();
  };

  return root;
}
